function runLine(v={}){return '<fieldset class="wh-run-line"><legend>Container weight</legend><label>Direction<select data-field="direction"><option '+(v.direction!=='Returned'?'selected':'')+'>Outgoing</option><option '+(v.direction==='Returned'?'selected':'')+'>Returned</option></select></label><label>Gross lb<input data-field="gross" type="number" min="0" step="0.001" required value="'+H(v.gross??'')+'"></label><label>Container<select data-field="container">'+Object.keys(W.TARES).map(x=>'<option '+((v.container||'Small Gaylord')===x?'selected':'')+'>'+H(x)+'</option>').join('')+'</select></label><label>Custom tare lb<input data-field="customTare" type="number" min="0" step="0.001" value="'+H(v.customTare??v.tare??'')+'"></label>'+btn('Remove container','run-remove')+'</fieldset>'}
function updateForm(){const form=document.getElementById('whRecord');if(!form)return;const k=form.elements.kind?.value;for(const [selector,hide] of [['[data-inkind]',k==='Financial'],['[data-financial]',k!=='Financial']]){const box=form.querySelector(selector);if(box){box.hidden=hide;for(const e of box.querySelectorAll('input,select'))e.disabled=hide}}const out=form.querySelector('#whNet');if(out){try{const n=W.net(form.elements.gross.value,form.elements.container.value,form.elements.customTare.value);out.textContent=F(n.net)+' lb net'}catch(e){out.textContent=e.message}}const hint=form.querySelector('#whUsdaHint');if(hint){const iid=form.elements.itemId.value,period=form.elements.month.value;const prev=live(wh.db.usdaBalances).find(x=>x.itemId===iid&&x.month===W.prior(period));const received=live(wh.db.usdaReceipts).filter(x=>x.itemId===iid&&x.date.slice(0,7)===period).reduce((s,x)=>s+x.cases,0);hint.textContent='Detailed receipts this month: '+received+' cases. Previous ending: '+(prev?prev.ending+' cases':'not available; document your opening basis')+'. Monthly totals replace detailed receipts.';form.elements.received.disabled=form.elements.receivedSource.value==='ledger'}}


function loadSample(){canWrite();if(['donations','usdaItems','counts','transfers','drives','runs'].some(k=>live(wh.db[k]).length))throw Error('Use the example in an empty warehouse workspace so it cannot mix with saved records.');const memory={getItem:()=>null,setItem:()=>{}},s=new W.Store(memory);s.db=JSON.parse(JSON.stringify(wh.db));const period=m(),d=period+'-15',last=new Date(Date.UTC(Number(period.slice(0,4)),Number(period.slice(5,7)),0)).toISOString().slice(0,10);
s.donor({name:'Fictional Community Donor',email:'donor@example.invalid',address:'Fictional demonstration address',cityZip:'Example, UT'});s.donation({date:d,donorName:'Fictional Community Donor',kind:'Food',type:'General Donation',receivedBy:'Demo staff',gross:1115,container:'Small Gaylord',email:'donor@example.invalid',emailRequested:true,description:'Fictional food for the walkthrough'});
s.donation({date:d,donorName:'Fictional Financial Donor',kind:'Financial',type:'General Donation',receivedBy:'Demo staff',amount:250,paymentMethod:'Cash',designation:'Fictional general support'});
const item=s.usdaItem({name:'Fictional USDA Beans',itemCode:'DEMO-USDA-1',packageSize:'12 × 1 lb',poundsPerCase:12});s.usdaReceive({date:d,itemId:item.id,cases:20,reference:'DEMO receipt 1'});s.usdaBalance({month:period,itemId:item.id,beginning:40,receivedSource:'ledger',ending:50,openingReason:'Fictional opening count for demonstration'});
const drive=s.drive({name:'Fictional Neighborhood Food Drive',owner:'Demo coordinator',location:'Bountiful',start:period+'-01',end:last,goal:500});s.driveEntry({date:d,driveId:drive.id,containerNumber:'DEMO-1',gross:150,container:'Wood pallet',stockKind:'Food'});
for(const [recipient,bucket,gross]of [['Fictional Partner Pantry','Partners / pantry deliveries',100],['Fictional School','Pantry Packs',50],['Fictional Recycling Log','Waste / recycling',20]])s.transfer({date:d,recipient,bucket,gross,container:'No container / already net',stockKind:'Food',categories:[bucket==='Pantry Packs'?'Pantry Packs':bucket==='Waste / recycling'?'Waste / Recycling':'Dry Goods'],reason:'Synthetic walkthrough'});
s.run({date:d,location:'Fictional Mobile Pantry Stop',completed:true,entries:[{direction:'Outgoing',gross:560,container:'Blue cart · 6 wheels'},{direction:'Returned',gross:160,container:'Blue cart · 6 wheels'}]});
s.weight({category:'Cereal',container:'Small Gaylord',netPounds:200,effective:period+'-01',source:'Fictional reviewed measurements — not pantry-approved values'});s.physical({month:period,date:last,category:'Cereal',stockKind:'Food',container:'Small Gaylord',quantity:2,fraction:1});s.countHeader({month:period,date:last,countedBy:'Demo inventory team'});s.reconcile({month:period,opening:2000,preparer:'Demo staff',openingReason:'Fictional opening physical count',truckDeduction:true,incomingReviewed:true,outgoingReviewed:true,notes:'Example policy choice only; BFP must confirm the actual truck treatment.'});s.snapshot(period,'Demo reviewer','Synthetic walkthrough, not BFP acceptance');
wh.commit('Load fictional warehouse walkthrough',period,n=>Object.assign(n,s.db));day=d;route('usda');toast('Fictional walkthrough loaded in this browser only. Actual BFP settings still require approval.')}

function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}

let importHeader=1,importChoices={},importMonth="";
function rawImportRows(){return draftImport?.kind==='csv'?draftImport.rows:draftImport?.kind==='xlsx'?draftImport.sheets.find(x=>x.name===selectedSheet)?.rows.map(x=>x.values):[]}
const choose=(label,name,opts,value)=>select(label,name,opts,importChoices[name]??value);
function mappingPanel(){if(!draftImport||draftImport.kind==='pdf')return '';const rows=rawImportRows(),headers=rows?.[importHeader-1]||[],choices=[['','Not in this file'],...headers.map((h,i)=>[String(i),(i+1)+': '+String(h||'Unnamed column')])],guess=re=>{const i=headers.findIndex(x=>re.test(String(x||'')));return i<0?'':String(i)};return '<details class="wh-mapping" open><summary>Match this file’s columns</summary><p>Choose the actual source columns. Weight must already be pounds; case quantities are not pounds. A source reference column or a unique batch reference is required.</p><div class="wh-form-grid">'+field('Header row number','whHeaderRow','number',importHeader,'min="1" max="100" step="1"')+choose('Record type','whTarget',[['donation','Incoming food / Grocery Rescue'],['usda','USDA case receipts']],'donation')+choose('Date column','whMapDate',choices,guess(/^date$|pickup.*date|receipt.*date|donation.*date/i))+choose('Donor / organization column','whMapDonor',choices,guess(/^donor$|donor.*name|organization|business.*name/i))+choose('Weight in pounds column','whMapPounds',choices,guess(/^net_pounds$|net.*weight|total.*pounds|total.*lbs|^pounds$|gross.*weight/i))+choose('Source column','whMapSource',choices,guess(/^source$/i))+choose('Unique reference column','whMapRef',choices,guess(/^reference$|invoice.*number|donation.*id|record.*id/i))+field('Batch reference if no reference column','whBatchRef','text',importChoices.whBatchRef||'')+choose('Default source if not in a column','whDefaultSource',['Grocery Rescue','Community','Utah Food Bank','Other'],'Grocery Rescue')+choose('USDA item-code column','whMapItem',choices,guess(/^item_code$|item.*code/i))+choose('USDA received-cases column','whMapCases',choices,guess(/^cases$|cases.*received/i))+'</div></details>'}

function importsPanel(){let html=card('Review a file before adding records','<p>CSV, XLSX workbooks and text-based food-bank PDF invoices are read privately in this browser. Nothing is uploaded. Review the month, units and source references before saving.</p><div class="wh-toolbar"><label class="primary wh-file">Choose file<input id="whImportFile" type="file" accept=".csv,.xlsx,.pdf"></label>'+btn('Download CSV template','csv-template')+btn('Try a fictional import','import-example')+'</div><p>One source per measure: a monthly Grocery Rescue total replaces detailed Grocery Rescue pickups. An imported PDF is not automatically USDA food. Case and Each quantities are not pounds.</p>');
if(!draftImport)return html;html+=card('Selected source: '+draftImport.name,'<p>File fingerprint: '+H(draftImport.hash.slice(0,16))+'…</p>'+((draftImport.warnings||[]).length?'<ul>'+draftImport.warnings.map(x=>'<li>'+H(x)+'</li>').join('')+'</ul>':'')+'<div class="wh-form-grid">'+field('Reporting month for review','whImportMonth','month',importMonth||m())+(draftImport.kind==='xlsx'?select('Worksheet','whSheet',draftImport.sheets.map(s=>s.name),selectedSheet):'')+'</div>'+mappingPanel()+'<div class="wh-toolbar">'+btn('Prepare incoming record preview','import-plan','','primary')+(draftImport.kind==='xlsx'?btn('Review historical Incoming / Outgoing totals','import-legacy'):'')+btn('Clear selected file','import-clear')+'</div><p>The template uses date, donor, net_pounds, source and reference; other source headings can be matched above. USDA case receipts use date, item_code, cases, reference and type=usda. A blank date requires a reporting month and is labeled monthly, never a fabricated daily receipt. Spreadsheet rows with broken formulas require correction in the source.</p>');
if(importPlan?.legacy){const p=importPlan.legacy;html+=card('Historical workbook review · '+p.month,table2(['Column','Source heading','Pounds'],Object.entries(p.columns).map(([k,v])=>[H(k),H(v.label),F(v.pounds)]))+field('Reason if replacing an existing historical source','whLegacyReason','text','')+'<p>This is a historical monthly source, separate from current warehouse records. Farmer / trash columns remain grouped as the supplied workbook does; confirm that mapping with pantry staff. Zero blank templates and broken formula cells are not accepted.</p>'+btn('Save reviewed historical totals','import-commit','','primary'))}
else if(importPlan){html+=card('Incoming preview · '+importPlan.rows.length+' records',table2(['Date / period','Donor / item','Source reference','Amount / quantity'],importPlan.rows.slice((importPlan.page||0)*50,((importPlan.page||0)+1)*50).map(x=>[H(x.value.granularity==='month'?x.value.date.slice(0,7)+' (monthly)':x.value.date),H(x.value.donorName||wh.db.usdaItems.find(i=>i.id===x.value.itemId)?.name),H(x.value.sourceRef||x.value.reference),x.kind==='usdaReceive'?F(x.value.cases)+' cases':F(x.value.gross)+' lb']))+'<p>Page '+((importPlan.page||0)+1)+' of '+Math.ceil(importPlan.rows.length/50)+'. Review every page before saving. Any invalid or repeated source line prevents the whole file from being added.</p><div class="wh-toolbar">'+((importPlan.page||0)>0?btn('Previous preview page','import-page',String(importPlan.page-1)):'')+(((importPlan.page||0)+1)*50<importPlan.rows.length?btn('Next preview page','import-page',String((importPlan.page||0)+1)):'')+'</div>'+btn('Save reviewed records','import-commit','','primary'))}return html}
function makePlan(){if(!draftImport)throw Error('Choose a source file first.');const period=document.querySelector('[name=whImportMonth]').value;W.month(period);let rows=[];
if(draftImport.kind==='pdf'){for(const [i,r] of draftImport.rows.entries()){const d=IO.sourceDate(r.date);if(!d)throw Error('The invoice date could not be verified. Use a reviewed CSV with a date.');if(!Number.isFinite(r.gross)||r.gross<0)throw Error('Review the invoice gross-pound field.');rows.push({kind:'donation',value:{date:d,donorName:'Utah Food Bank',kind:'Food',type:'Business Donation',receivedBy:'Reviewed file import',source:'Utah Food Bank',sourceRef:r.invoice+' · line '+(i+1)+' · '+r.itemCode,description:r.name+'; source '+r.quantity+' '+r.unit,container:'No container / already net',gross:r.gross,sourceKey:r.sourceKey}})}}

else{const raw=rawImportRows();if(!raw?.length)throw Error('Worksheet is empty.');const sourceHeaders=raw[importHeader-1]||[],heads=sourceHeaders.map(x=>String(x||'').trim().toLowerCase()),get=name=>document.querySelector('[name='+name+']')?.value??'',col=(row,name)=>get(name)===''?'':row[Number(get(name))]??'',batch=get('whBatchRef').trim();if(get('whMapRef')===''&&!batch)throw Error('Choose a unique source reference column or enter a stable batch reference.');for(let j=importHeader;j<raw.length;j++){const cells=raw[j];if(!cells.some(x=>String(x??'').trim()))continue;if(cells.some(x=>String(x).includes('#SOURCE_FORMULA_REVIEW')||String(x).startsWith('#REF')))throw Error('Source formula needs review on row '+(j+1)+'.');const normal=Object.fromEntries(heads.map((x,i)=>[x,cells[i]??''])),ref=String(col(cells,'whMapRef')||batch+'|line|'+(j+1)).trim();if(!ref)throw Error('A source reference is required on row '+(j+1)+'.');const rawDate=col(cells,'whMapDate'),parsed=IO.sourceDate(rawDate);if(rawDate&&!parsed)throw Error('Invalid date on row '+(j+1)+'.');const d=parsed||period+'-01',sourceKey='source|'+ref,isUsda=get('whTarget')==='usda'||String(normal.type).toLowerCase()==='usda';if(isUsda){if(!parsed)throw Error('USDA case receipts require an actual receipt date. Use monthly balances for monthly totals.');const code=String(col(cells,'whMapItem')||normal.item_code||''),item=live(wh.db.usdaItems).find(x=>x.itemCode&&x.itemCode===code);if(!item)throw Error('Create or verify USDA item code '+code+' before importing.');rows.push({kind:'usdaReceive',value:{date:d,itemId:item.id,cases:col(cells,'whMapCases')||normal.cases,reference:ref,sourceKey}})}else{const pounds=String(col(cells,'whMapPounds')).replaceAll(',','');if(!pounds.trim()||!Number.isFinite(Number(pounds))||Number(pounds)<0)throw Error('Review the pounds column on row '+(j+1)+'. Case or Each counts are not pounds.');const source=String(col(cells,'whMapSource')||get('whDefaultSource'));rows.push({kind:'donation',value:{date:d,granularity:parsed?'day':'month',donorName:String(col(cells,'whMapDonor')||source||'Door'),kind:normal.kind==='Nonfood'?'Nonfood':'Food',type:normal.donation_type||'Business Donation',receivedBy:'Reviewed file import',source,sourceRef:ref,sourceKey,gross:Number(pounds),container:'No container / already net',description:normal.description||''}})}}}
if(!rows.length)throw Error('There are no valid source rows.');const memory={getItem:()=>null,setItem:()=>{}},scratch=new W.Store(memory);scratch.db=JSON.parse(JSON.stringify(wh.db));scratch.importRows(importKey(),rows,draftImport.name);importPlan={rows,page:0,seen:[0]};render()}
function commitImport(){canWrite();if(!draftImport||!importPlan)throw Error('Prepare and review a preview first.');if(importPlan.legacy){if(wh.db.imports.some(x=>x.hash===draftImport.hash&&x.sheet===selectedSheet))throw Error('This worksheet has already been imported.');const p=importPlan.legacy,existing=live(wh.db.legacyMonths).find(x=>x.month===p.month),replaces=existing&&(p.sourceType==='incoming'?existing.incomingFood!=null:!!existing.buckets),replacementReason=document.querySelector('[name=whLegacyReason]')?.value||'';if(replaces)W.text(replacementReason,'reason for replacing this historical source');wh.commit('Reviewed historical workbook',p.month,n=>{const old=live(n.legacyMonths).find(x=>x.month===p.month),saved={...old,...p,id:old?.id||p.id,incomingFood:p.incomingFood??old?.incomingFood,buckets:p.buckets||old?.buckets,sourceRefs:[...(old?.sourceRefs||[]),{file:draftImport.name,sheet:selectedSheet,hash:draftImport.hash}],issues:[]};if(saved.incomingFood==null)saved.issues.push('Incoming workbook source is missing.');if(!saved.buckets)saved.issues.push('Outgoing workbook source is missing.');if(old)n.audit.unshift({id:W.id(),at:new Date().toISOString(),action:'Historical source review detail',record:saved.id,reason:replacementReason||'Add complementary reviewed source',before:JSON.parse(JSON.stringify(old)),after:JSON.parse(JSON.stringify(saved))});n.legacyMonths=n.legacyMonths.filter(x=>x.id!==saved.id);n.legacyMonths.push(saved);n.imports.push({id:W.id(),hash:draftImport.hash,sheet:selectedSheet,source:draftImport.name,at:new Date().toISOString()})})}else{if(new Set(importPlan.seen).size<Math.ceil(importPlan.rows.length/50))throw Error('Review every preview page before saving.');wh.importRows(importKey(),importPlan.rows,draftImport.name);}draftImport=null;importPlan=null;saveMessage('Reviewed source saved once.')}
function printDocument(title,html,landscape=false){showDialog(title,'<div class="wh-toolbar no-print">'+btn('Print / save as PDF','print-browser','','primary')+'<p>Demonstration copy · review before operational use.</p></div><article id="whPrint" class="'+(landscape?'wh-landscape':'wh-portrait')+'">'+html+'</article>',null)}
const reportHead=title=>'<div class="wh-print-head"><img src="logo.png" alt="Bountiful Food Pantry"><div><h1>'+H(title)+'</h1><p>480 East 150 North · Bountiful, UT 84010 · 801-299-8464</p></div></div><p class="wh-demo-mark">DEMONSTRATION · SYNTHETIC DATA · NOT AN OFFICIAL SUBMISSION</p>';
function receipt(x){return reportHead('Donation receipt')+'<p><strong>Receipt '+H(x.receiptNumber)+'</strong> · '+H(x.date)+'</p><h2>'+H(x.donorName)+'</h2><p>'+H(x.address||'')+'<br>'+H(x.cityZip||'')+'<br>'+H(x.email||'')+'</p>'+table2(['Contribution','Details'],[['Donation type',H(x.type)],['Financial',x.kind==='Financial'?'$'+F(x.amount)+' · '+H(x.paymentMethod)+' · '+H(x.paymentDetails):'—'],['In-kind goods',x.kind!=='Financial'?H(x.kind)+' · '+F(x.net)+' net lb':'—'],['Description',H(x.description)],['Project / designation',H(x.designation)],['Received by',H(x.receivedBy)]])+'<p>In-kind value is determined by the donor. This demonstration is not a tax receipt. BFP must approve the final acknowledgment wording before production use.</p><p>Receipt email: '+H(x.delivery)+'. No email has been sent by this demo.</p>'}
function transferPrint(x){return reportHead('Non-USDA food transfer log')+table2(['Sending organization','Receiving organization'],[['Bountiful Food Pantry<br>480 East 150 North, Bountiful UT 84010',H(x.recipient)+'<br>'+H(x.address)]])+table2(['Date','Item / code','Unit / package size','Cases','Net lb'],[[H(x.date),H(x.items)+' '+H(x.itemCode),H(x.packSize),F(x.cases),F(x.net)]])+table2(['Categories','Purpose / reason'],[[H(x.categories.join(', ')),H(x.bucket)+' · '+H(x.reason)]])+table2(['TCS food temperatures','When sent (°F)','When received (°F)'],[['If applicable',F(x.tempOut),F(x.tempIn)]])+table2(['Representative','Sending site','Receiving site'],[['Name',H(x.donatingRep),H(x.receivingRep)],['Phone',H(x.donatingPhone),H(x.receivingPhone)],['Email',H(x.donatingEmail),H(x.receivingEmail)]])+'<p>Sending representative signature: ________________________</p><p>Receiving representative signature: ________________________</p><p>Email status: '+H(x.delivery)+'</p>'}
function prepareUsda(){const rows=W.ledger(wh.db,m());if(!rows.length)throw Error('Record at least one USDA monthly balance first.');const issues=rows.flatMap(x=>x.issues);const missing=live(wh.db.usdaReceipts).filter(x=>x.date.slice(0,7)===m()&&!rows.some(r=>r.itemId===x.itemId));if(issues.length||missing.length)throw Error('Resolve USDA balance issues and missing ending counts before preparing the report.');showDialog('Prepare USDA monthly report','<form id="whReport" class="wh-form-grid">'+field('Agency name','agency','text',reportMeta.agency||'Bountiful Food Pantry','required')+field('Reporting month','month','month',m(),'readonly')+field('Households served (reviewed source)','households','number',reportMeta.households??'','min="0" step="1"')+field('Individuals served (reviewed source)','individuals','number',reportMeta.individuals??'','min="0" step="1"')+field('Soup kitchen breakfasts, if applicable','breakfasts','number',reportMeta.breakfasts??'','min="0" step="1"')+field('Soup kitchen lunches, if applicable','lunches','number',reportMeta.lunches??'','min="0" step="1"')+area('Service-count source / verification note','basis',reportMeta.basis||'')+field('Preparer name','preparer','text',reportMeta.preparer||'','required')+field('Authorized signer title','signerTitle','text',reportMeta.signerTitle||'')+'<p class="wh-wide">Service counts are not inferred from incomplete or duplicate service databases. Enter reviewed counts and document their source. The signature remains blank for an authorized person.</p><p id="whError" class="wh-error wh-wide" role="alert"></p><button class="primary" type="submit">Prepare printable report</button></form>',f=>{reportMeta=Object.fromEntries(new FormData(f));const saved={id:W.id(),month:m(),rows:JSON.parse(JSON.stringify(rows)),meta:{...reportMeta},at:new Date().toISOString(),sourceRevision:wh.db.revision};wh.commit('Prepare USDA report',saved.id,n=>n.usdaReports.push(saved));const p=usdaPrint(saved.rows,saved.meta);document.getElementById('whDialog').close();render();printDocument('USDA monthly inventory report',p,true)})}
function usdaPrint(rows,meta){const chunks=[];for(let i=0;i<rows.length;i+=14)chunks.push(rows.slice(i,i+14));while(chunks.length<2)chunks.push([]);return chunks.map((group,i)=>'<section class="wh-report-page">'+reportHead('USDA Monthly Inventory Report')+'<p><strong>Agency:</strong> '+H(meta.agency)+' <strong>Month:</strong> '+H(meta.month)+' <strong>Page:</strong> '+(i+1)+' of '+chunks.length+'</p>'+table2(['USDA commodity foods','Unit weight / package size','Beginning cases','Received cases','Distributed cases','Ending cases'],group.map(x=>[H(x.item?.name),H(x.item?.packageSize)+'<small>'+F(x.weightSnapshot)+' lb / case</small>',F(x.beginning),F(x.received),F(x.distributed),F(x.ending)]))+ (i===chunks.length-1?'<h2>Monthly totals</h2>'+table2(['Beginning cases','Received cases','Distributed cases','Ending cases','Ending food pounds'],[[...['beginning','received','distributed','ending','endingPounds'].map(k=>F(rows.reduce((s,x)=>s+x[k],0)))]])+'<p>Households served: '+H(meta.households||'Not supplied')+' &nbsp; Individuals served: '+H(meta.individuals||'Not supplied')+' &nbsp; Soup kitchen meals: '+((meta.breakfasts!==''&&meta.breakfasts!=null)||(meta.lunches!==''&&meta.lunches!=null)?F(Number(meta.breakfasts||0)+Number(meta.lunches||0)):'Not applicable / not supplied')+' · Breakfasts: '+H(meta.breakfasts===''?'Not supplied':meta.breakfasts??'Not supplied')+' · Lunches: '+H(meta.lunches===''?'Not supplied':meta.lunches??'Not supplied')+'</p><p>Service-count basis: '+H(meta.basis||'Review required')+'</p><p>Prepared by: '+H(meta.preparer)+'</p><p>For the authorized signer to review: I certify that, to the best of my knowledge and belief, this report is true and correct, supporting records are available, and it follows the contract terms. No certification is made by the software.</p><p>Authorized signature: _________________________________ &nbsp; Title: '+H(meta.signerTitle||'________________________')+' &nbsp; Date: ______________</p>':'<p>Continued on next page.</p>')+'<p class="wh-print-note">Beginning + received − ending = distributed. Case weights are commodity-specific. Detailed receipts or the reviewed monthly received total is used once. Recreated from the supplied tracking form; final agency submission layout and service definitions require BFP approval.</p></section>').join('')}
function closePrint(r){return reportHead('Monthly food reconciliation')+'<h2>'+H(r.month)+'</h2>'+table2(['Measure','Food pounds'],[['Opening',F(r.opening)],['Incoming, including Grocery Rescue',F(r.received)],['Ending, including USDA once',F(r.ending)],['Total distributed',F(r.distributed)],...Object.entries(r.buckets).map(([k,v])=>[H(k),F(v)]),['Residual to clients',F(r.client)]])+'<p>Truck deduction: '+(r.truckDeduction===null?'Decision pending':r.truckDeduction?'Deducted':'Retained in residual')+'</p><p>'+(r.issues.length?'Needs attention: '+H(r.issues.join(' ')):'Numerical checks passed; staff review still required.')+'</p>'}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-wh]');if(!b)return;e.preventDefault();try{const a=b.dataset.wh,k=b.dataset.id||'';if(a==='help')return showDialog('Warehouse quick guide','<ol><li><strong>Receive a donation:</strong> choose food, nonfood or financial. For goods, enter gross weight and container; net weight calculates automatically. Print the saved receipt.</li><li><strong>Send food:</strong> record a partner transfer. For the mobile pantry, start a run with loaded containers and edit the same run when food returns.</li><li><strong>Count inventory:</strong> enter container counts and fullness, or measured net pounds. Resolve unknown weights and record who counted.</li><li><strong>Track USDA:</strong> add a commodity and its case weight, record received cases, then enter beginning and ending cases for the month. Prepare and retain the report.</li><li><strong>Finish the month:</strong> review opening inventory, source completeness and the truck policy. Resolve issues, then save a review snapshot.</li><li><strong>Keep a copy:</strong> download a warehouse backup regularly. This demo saves only on this browser, and email requests are not delivered.</li></ol>',null);if(a==='tab')return route(k);if(a==='sample')return loadSample();if(a==='thankyou-batch')return printDocument('Monthly donor thank-you batch',thanksPrint());if(a==='donor-csv')return exportCsv('bfp-donor-totals-'+m()+'.csv',[['donor','donation_count','financial_dollars','food_pounds','nonfood_pounds'],...donorTotals().map(x=>[x.name,x.receipts,x.financial,x.food,x.nonfood])]);if(a==='dismiss')return document.getElementById('whDialog').close();if(a==='new')return recordForm(k);if(a.startsWith('new-'))return recordForm(a.slice(4));if(a==='edit'){const [kind,rid]=k.split('|');return recordForm(kind,rid)}if(a==='void'){canWrite();const [kind,rid]=k.split('|');showDialog('Void this record','<form id="whVoid">'+area('Reason for voiding','reason','','required')+'<p>The record and reason remain in history. Totals exclude the voided record.</p><p id="whError" role="alert" class="wh-error"></p><button class="primary">Void record</button></form>',f=>{wh.void(mapTable[kind],rid,new FormData(f).get('reason'));document.getElementById('whDialog').close();saveMessage('Record voided; history retained.')});return}
if(a==='run-line'){document.getElementById('whRunEntries').insertAdjacentHTML('beforeend',runLine());return}if(a==='run-remove')return b.closest('fieldset').remove();
if(a==='print'){const [kind,rid]=k.split('|'),x=wh.db[mapTable[kind]].find(x=>x.id===rid);return printDocument(kind==='donation'?'Donation receipt':'Non-USDA transfer log',kind==='donation'?receipt(x):transferPrint(x),kind==='transfer')}
if(a==='usda-saved'){const saved=wh.db.usdaReports.find(x=>x.id===k);return printDocument('Saved USDA report',usdaPrint(saved.rows,saved.meta),true)}if(a==='print-usda'||a==='usda-report')return prepareUsda();if(a==='print-close')return printDocument('Monthly reconciliation',closePrint(W.reconciliation(wh.db,m())));
if(a==='print-count'){const c=W.count(wh.db,m());return printDocument('Physical inventory count',reportHead('Physical inventory count')+'<h2>'+H(m())+'</h2><p>Count date: '+H(c.header?.date||'Not supplied')+' · Counted by: '+H(c.header?.countedBy||'Not supplied')+'</p>'+table2(['Category','Container','Count','Fullness','Net food / goods lb','Basis'],c.rows.map(x=>[H(x.category),H(x.container),F(x.quantity),F(x.fraction),F(x.pounds),H(x.basis)]))+'<p>USDA ending pounds: '+F(c.usda.reduce((n,x)=>n+(x.endingPounds||0),0))+' · Food total: '+(c.complete?F(c.food):'Incomplete')+' · Nonfood: '+F(c.nonfood)+'</p>',true)}
if(a==='print-browser'){document.body.dataset.whPrinting='true';window.print();delete document.body.dataset.whPrinting;return}
if(a==='snapshot'){canWrite();showDialog('Save month-end review','<form id="whSnapshot">'+field('Reviewer','reviewer','text','','required')+area('Review notes','notes')+'<p>This retains the current values with a time and source revision. Browser storage is editable and is not a protected production lock.</p><p id="whError" class="wh-error" role="alert"></p><button class="primary">Save snapshot</button></form>',f=>{const data=Object.fromEntries(new FormData(f));wh.snapshot(m(),data.reviewer,data.notes);document.getElementById('whDialog').close();saveMessage('Review snapshot saved.')});return}
if(a==='snapshot-view'){const x=wh.db.snapshots.find(x=>x.id===k);return printDocument('Saved month-end snapshot',closePrint(x.values)+'<p>Reviewed by '+H(x.reviewer)+' · '+H(x.at)+' · source revision '+x.sourceRevision+'</p><p>'+H(x.notes)+'</p>')}
if(a==='add-location'){canWrite();showDialog('Add a warehouse location','<form id="whLocation">'+field('Location name','name','text','','required')+'<p id="whError" class="wh-error" role="alert"></p><button class="primary">Save location</button></form>',f=>{const name=W.text(new FormData(f).get('name'),'location');if(wh.db.locations.some(x=>x.toLowerCase()===name.toLowerCase()))throw Error('This location already exists.');wh.commit('Add location',name,n=>n.locations.push(name));document.getElementById('whDialog').close();saveMessage('Location saved.')});return}
if(a==='legacy-backup'){const records={};for(let j=0;j<localStorage.length;j++){const key=localStorage.key(j);if(key.startsWith('bfp-')){try{records[key]=JSON.parse(localStorage.getItem(key))}catch{records[key]=localStorage.getItem(key)}}}return download('bfp-all-demo-records-'+today()+'.json',JSON.stringify({format:'bfp-demo-migration-source',exportedAt:new Date().toISOString(),records},null,2))}if(a==='backup-export'){download('bfp-warehouse-backup-'+today()+'.json',JSON.stringify(wh.export(),null,2));return}if(a==='backup-choose'){document.getElementById('whBackupFile').click();return}
if(a==='csv-export'){const rows=[['receipt','date','donor','kind','type','source','net_pounds','amount','status'],...selectedRows('donations').map(x=>[x.receiptNumber,x.date,x.donorName,x.kind,x.type,x.source,x.net,x.amount,x.delivery])];return exportCsv('bfp-donations-'+m()+'.csv',rows)}
if(a==='csv-template')return exportCsv('bfp-incoming-template.csv',[['date','donor','net_pounds','source','reference','kind','donation_type','description','type','item_code','cases']]);
if(a==='import-page'){if(!importPlan?.rows)throw Error('Prepare an import preview first.');const page=Number(k);if(!Number.isInteger(page)||page<0||page>=Math.ceil(importPlan.rows.length/50))throw Error('Choose a valid preview page.');importPlan.page=page;importPlan.seen.push(page);render();return}if(a==='import-example'){canWrite();draftImport=await IO.read(new File(['Pickup Date,Donor Name,Total Pounds,Donation ID\n'+m()+'-20,Fictional Import Donor,25,DEMO-IMPORT-'+m()+'-1\n'],'Fictional-grocery-rescue.csv',{type:'text/csv'}));selectedSheet='';importHeader=1;importChoices={};importMonth=m();importPlan=null;render();return}if(a==='import-clear'){draftImport=null;importPlan=null;render();return}if(a==='import-plan')return makePlan();if(a==='import-legacy'){const p=IO.legacy(draftImport.sheets.find(x=>x.name===selectedSheet),document.querySelector('[name=whImportMonth]').value);importPlan={legacy:p};render();return}if(a==='import-commit')return commitImport();
}catch(err){toast(err.message);const box=document.getElementById('whError');if(box)box.textContent=err.message}});
function exportCsv(name,rows){const safe=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download(name,'\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('submit',e=>{if(!['whRecord','whVoid','whSnapshot','whLocation','whReport','whRestore'].includes(e.target.id))return;e.preventDefault();try{canWrite();editor?.(e.target)}catch(err){const box=document.getElementById('whError');if(box){box.textContent=err.message;box.scrollIntoView({block:'nearest'})}}});
document.addEventListener('input',e=>{if(e.target.closest('#whRecord'))updateForm()});
document.addEventListener('change',async e=>{try{if(e.target.name==='whImportMonth'){importMonth=e.target.value;importPlan=null;return render()}if(/^(whMap|whTarget|whDefaultSource|whBatchRef)/.test(e.target.name)){importChoices[e.target.name]=e.target.value;importPlan=null;return render()}if(e.target.name==='whHeaderRow'){importHeader=Number(e.target.value);importChoices={};if(!Number.isInteger(importHeader)||importHeader<1||importHeader>100)throw Error('Choose a header row from 1 to 100.');importPlan=null;return render()}if(e.target.name==='whDay'){day=e.target.value;return render()}if(e.target.name==='whSheet'){selectedSheet=e.target.value;importHeader=1;importChoices={};importPlan=null;return render()}if(e.target.closest('#whRecord')){if(e.target.name==='donorName'){const d=live(wh.db.donors).find(x=>x.name.toLowerCase()===e.target.value.toLowerCase());if(d)for(const k of ['address','cityZip','email'])e.target.form.elements[k].value=d[k]||''}updateForm()}
if(e.target.id==='whImportFile'){canWrite();const status=document.getElementById('toast');status.textContent='Reading source file privately…';draftImport=await IO.read(e.target.files[0]);if(draftImport.kind==='backup')throw Error('Use Records & backups to restore a backup.');selectedSheet=draftImport.sheets?.[0]?.name||'';importHeader=1;importChoices={};importMonth=m();importPlan=null;render();toast('File ready for review. Nothing has been imported yet.')}
if(e.target.id==='whBackupFile'){canWrite();if(!e.target.files[0]||e.target.files[0].size>15000000)throw Error('Choose a backup under 15 MB.');const pack=JSON.parse(await e.target.files[0].text());if(pack.format!=='bfp-warehouse-backup'||pack.version!==W.VERSION)throw Error('Not a supported BFP warehouse backup.');const current=wh.export();download('bfp-before-restore-'+today()+'.json',JSON.stringify(current,null,2));showDialog('Review backup restore','<form id="whRestore"><p>Backup date: '+H(pack.exportedAt)+' · revision '+H(pack.data?.revision)+'</p>'+table2(['Record group','Count'],Object.entries(pack.data||{}).filter(([,v])=>Array.isArray(v)).map(([k,v])=>[H(k),v.length]))+'<p>A current backup has been downloaded. Restoring replaces this browser’s warehouse records. Volunteer and service records are separate.</p>'+field('Type RESTORE to confirm','confirm','text','','required')+area('Restore reason','reason','','required')+'<p id="whError" class="wh-error" role="alert"></p><button class="primary">Restore reviewed backup</button></form>',f=>{const data=Object.fromEntries(new FormData(f));if(data.confirm!=='RESTORE')throw Error('Type RESTORE to confirm.');wh.restore(pack,data.reason);document.getElementById('whDialog').close();saveMessage('Warehouse backup restored.')})}
}catch(err){toast(err.message)}});
const baseOpen=openEntry;openEntry=function(type,program,repeat,editing){if(type==='food')return recordForm('donation');if(type==='outgoing')return recordForm('transfer');return baseOpen(type,program,repeat,editing)};
const baseStats=stats;stats=function(){const s=baseStats(),from=$('#from').value,to=$('#to').value;let total=0,gr=0;for(let period=from.slice(0,7);period<=to.slice(0,7);){const end=new Date(Date.UTC(Number(period.slice(0,4)),Number(period.slice(5,7)),0)).toISOString().slice(0,10);if(from<=period+'-01'&&to>=end){const inc=W.incoming(wh.db,period);total+=inc.food;gr+=inc.groceryRescue}else{const rows=W.incoming(wh.db,period).records.filter(x=>x.date>=from&&x.date<=to&&x.granularity!=='month'&&x.kind==='Food');total+=rows.reduce((n,x)=>n+x.net,0);gr+=rows.filter(x=>x.source==='Grocery Rescue').reduce((n,x)=>n+x.net,0);total+=live(wh.db.usdaReceipts).filter(x=>x.date>=from&&x.date<=to&&x.date.slice(0,7)===period&&!live(wh.db.usdaBalances).some(b=>b.month===period&&b.itemId===x.itemId&&b.receivedSource==='monthly-total')).reduce((n,x)=>n+x.cases*x.weightSnapshot,0)}const d=new Date(period+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);period=d.toISOString().slice(0,7)}s.incoming=W.round(total);s.rescue=W.round(gr);const periods=reportingMonths(),full=monthCoverage().ok,calcs=periods.map(p=>W.reconciliation(wh.db,p));s.out=full&&calcs.length&&calcs.every(r=>r.complete)?W.round(calcs.reduce((n,r)=>n+r.client,0)):'Not available';return s};

const priorBoardIntro=boardPresentationIntro;boardPresentationIntro=function(){const months=reportingMonths(),reviewed=months.filter(p=>live(wh.db.snapshots).some(x=>x.month===p)).length;return priorBoardIntro().replace(/\d+\/\d+ month-end staff reviews recorded/,reviewed+'/'+months.length+' warehouse review snapshots saved')};
const priorReadiness=boardReadiness;boardReadiness=function(){const r=priorReadiness();if(!r.months.length)return r;r.checks=r.checks.filter(x=>!['Warehouse physical counts','Saved staff review notes (not approval)','Pending warehouse adjustment requests','Warehouse data-quality review'].includes(x[0]));r.checks.push(['Warehouse inventory and month-end calculations',r.months.every(p=>W.reconciliation(wh.db,p).complete),r.months.map(p=>p+': '+(W.reconciliation(wh.db,p).issues.join(' ')||'Numerical checks passed; human review required')).join(' · ')]);r.checks.push(['Current warehouse review snapshots (not approval)',r.months.every(p=>live(wh.db.snapshots).some(x=>x.month===p&&x.sourceSignature===W.signature(wh.db,p))), 'The current records must match a saved review snapshot; corrections require a new review.']);return r};
marketReporting=function(){const period=m(),end=new Date(Date.UTC(Number(period.slice(0,4)),Number(period.slice(5,7)),0)).toISOString().slice(0,10),full=$('#from').value===period+'-01'&&$('#to').value===end,r=W.reconciliation(wh.db,period),a=full?marketAggregates().find(x=>x.month===period&&x.location==='bountiful'):null,ratio=(n,d)=>Number.isFinite(n)&&Number.isFinite(Number(d))&&Number(d)>0?F(n/Number(d)):'Not available';return card('Market pounds and service measures', '<p>Client pounds come from the warehouse month-end residual. Service counts and actual staffed shifts come from the monthly PantrySoft summary. Daily example visits are separate from that source.</p>'+table2(['Measure','Calculated value','Basis'],[['Client food pounds',full?F(r.client):'Not available','Opening + incoming − ending, less reviewed outgoing allocations'],['Average pounds per household visit',ratio(full?r.client:null,a?.duplicated_households),'Warehouse residual ÷ duplicated households from monthly summary'],['Average pounds per individual visit',ratio(full?r.client:null,a?.duplicated_individuals),'Warehouse residual ÷ duplicated individuals from monthly summary'],['Average households per Market shift',ratio(a?.duplicated_households,a?.market_shifts),'Monthly duplicated households ÷ recorded actual shifts']])+(!full?'<p>Select one complete calendar month.</p>':r.issues.length?'<p>Warehouse review needed: '+H(r.issues.join(' '))+'</p>':'')+'<p>All current sources are synthetic demo records. The approved PantrySoft export and BFP calculation policy must be verified before production use.</p>')}

const baseRender=render;
window.addEventListener('bfp-warehouse-reset',()=>{wh=new W.Store(localStorage);draftImport=null;importPlan=null});
