render=function(){baseRender();warehouseEnhance()};
const priorBoard=board;board=function(s){let html=priorBoard(s);const r=W.reconciliation(wh.db,m()),full=$('#from').value===m()+'-01'&&$('#to').value===new Date(Number(m().slice(0,4)),Number(m().slice(5,7)),0).toLocaleDateString('en-CA'),available=full&&$('#location').value!=='north';const panel='<section class="report-food-flow wh-board-flow"><div><span>WAREHOUSE FOOD RECEIVED</span><strong>'+F(available?r.received:null)+'<small> lb</small></strong><p>Current warehouse source, including USDA and Grocery Rescue</p></div><div><span>ENDING FOOD INVENTORY</span><strong>'+F(available?r.ending:null)+'<small> lb</small></strong><p>Physical food plus USDA ending cases, counted once</p></div><div><span>RESIDUAL TO CLIENTS</span><strong>'+F(available?r.client:null)+'<small> lb</small></strong><p>'+(available?H(r.issues.join(' ')||'Numerical checks passed · staff review required'):'Select one complete calendar month for warehouse reconciliation.')+'</p></div></section>';const rows=[['Food received (Grocery Rescue included)',available?F(r.received):'Not available'],['Ending physical food, USDA included once',available?F(r.ending):'Not available'],['Total distributed: opening + incoming − ending',available?F(r.distributed):'Not available'],['Partner pantry deliveries',available?F(r.buckets['Partners / pantry deliveries']):'Not available'],['Pantry Packs outgoing food',available?F(r.buckets['Pantry Packs']):'Not available'],['Net mobile pantry distribution',available?F(r.buckets['Mobile pantry']):'Not available'],['Residual food to clients',available?F(r.client):'Not available']];const block='<h3>Warehouse food and inventory</h3>'+table2(['Reviewed monthly measure','Food pounds'],rows)+'<p class="report-caption">'+(available?H(r.issues.join(' ')||'Numerical checks passed; human review required.'):'Choose one complete calendar month for warehouse inventory reporting.')+' Truck treatment: '+(r.truckDeduction===null?'decision pending':r.truckDeduction?'deducted from residual':'retained in residual')+'. Off-site household forms do not collect food weights.</p>';html=html.replace(/<h3>Food received and transfers<\/h3>[\s\S]*?<p class="report-caption">[\s\S]*?<\/p>/,()=>block);html=html.replace('Food movements; not inventory balance','Connected food receipts, USDA cases, counts and reconciliation');return html};
const finder=$('#taskFinder');if(finder)finder.addEventListener('input',()=>{const q=finder.value.trim().toLowerCase();const entries=[['usda','usda commodity cases government inventory'],['donations','donation receipt donor receiving'],['runs','truck warehouse dispatch return containers'],['count','physical inventory count'],['close','reconcile month end close'],['backup','backup audit history restore']].filter(([,words])=>q&&q.split(/\s+/).every(w=>words.includes(w)));if(!entries.length||demoRole==='volunteer')return;const box=$('#taskResults');box.querySelector('p')?.remove();for(const [t]of entries)box.insertAdjacentHTML('beforeend',link(tabNames[t],t));box.hidden=false;finder.setAttribute('aria-expanded','true')});
